import adsk.core, adsk.fusion, json, math

def run(context):
    app = adsk.core.Application.get()
    design = app.activeProduct
    root = design.rootComponent
    body = root.bRepBodies.item(0)

    def to_mm(cm_val):
        return round(cm_val * 10.0, 3)

    hexes = []
    for face in body.faces:
        geom = face.geometry
        if geom.surfaceType == adsk.core.SurfaceTypes.PlaneSurfaceType:
            loops = face.loops
            # outer loop edge count
            try:
                outer = None
                for lp in loops:
                    if lp.isOuter:
                        outer = lp
                        break
                if outer is None:
                    continue
                edgeCount = outer.edges.count
            except:
                continue
            if edgeCount == 6:
                bb = face.boundingBox
                cx = to_mm((bb.minPoint.x+bb.maxPoint.x)/2)
                cy = to_mm((bb.minPoint.y+bb.maxPoint.y)/2)
                dist = round(math.hypot(cx,cy),2)
                if dist > 80:  # perimeter bosses only
                    area = round(face.area*100,3)  # cm^2 -> mm^2
                    hexes.append({'cx':cx,'cy':cy,'dist_from_center':dist,'area_mm2':area,'numLoops':loops.count})

    # dedupe near-identical (top and bottom face of same boss)
    print(json.dumps({'hex_perimeter_faces_found': len(hexes), 'hexes': hexes[:40]}))

