import adsk.core, adsk.fusion, json, math

def run(context):
    app = adsk.core.Application.get()
    design = app.activeProduct
    root = design.rootComponent
    body = root.bRepBodies.item(0)

    def mm(v):
        return round(v * 10.0, 3)

    hexfaces = []
    for i, face in enumerate(body.faces):
        g = face.geometry
        if g.surfaceType != adsk.core.SurfaceTypes.PlaneSurfaceType:
            continue
        outer = None
        for lp in face.loops:
            if lp.isOuter:
                outer = lp
                break
        if outer is None or outer.edges.count != 6:
            continue
        bb = face.boundingBox
        cx, cy = mm((bb.minPoint.x+bb.maxPoint.x)/2), mm((bb.minPoint.y+bb.maxPoint.y)/2)
        if math.hypot(cx, cy) < 80:
            continue
        pl = adsk.core.Plane.cast(g)
        n = pl.normal
        # collect unique vertex coords of the outer loop
        vs = []
        for e in outer.edges:
            for v in [e.startVertex, e.endVertex]:
                p = (mm(v.geometry.x), mm(v.geometry.y), mm(v.geometry.z))
                if p not in vs:
                    vs.append(p)
        hexfaces.append({
            'idx': i,
            'center': [cx, cy],
            'z_min': mm(bb.minPoint.z), 'z_max': mm(bb.maxPoint.z),
            'normal': [round(n.x,3), round(n.y,3), round(n.z,3)],
            'area_mm2': round(face.area*100, 2),
            'loopCount': face.loops.count,
            'verts': vs
        })

    print(json.dumps({'count': len(hexfaces), 'faces': hexfaces}))

