import adsk.core, adsk.fusion, json

def run(context):
    app = adsk.core.Application.get()
    design = app.activeProduct
    root = design.rootComponent
    body = root.bRepBodies.item(0)

    def cm(mm_val):
        return mm_val / 10.0

    names = {0:'INSIDE', 1:'ON', 2:'OUTSIDE', -1:'UNKNOWN'}

    out = {}

    # Probe the vertical extent of solid at several hex-tab centers
    tabs = {
        'tabA_(-95,13.66)_normalPlusZ': (-95.0, 13.66),
        'tabB_(-95,33.66)_normalMinusZ': (-95.0, 33.66),
        'tabC_(-13.66,95)_normalMinusZ': (-13.66, 95.0),
        'tabD_(-33.66,95)_normalPlusZ': (-33.66, 95.0),
    }
    probes = {}
    for label,(x,y) in tabs.items():
        col = []
        for z in [0.5, 2.0, 4.0, 4.9, 5.1, 6.0, 8.0, 9.5]:
            p = adsk.core.Point3D.create(cm(x), cm(y), cm(z))
            col.append((z, names.get(body.pointContainment(p), '?')))
        probes[label] = col
    out['tab_z_probes'] = probes

    # Also probe main plate body for reference
    refcol = []
    for z in [0.5, 2.0, 5.0, 8.0, 9.5]:
        p = adsk.core.Point3D.create(cm(-60.0), cm(0.0), cm(z))
        refcol.append((z, names.get(body.pointContainment(p), '?')))
    out['reference_plate_body_(-60,0)'] = refcol

    # Dump small sketches that may hold uncut hole geometry
    def dump(skname, limit=30):
        sk = root.sketches.itemByName(skname)
        if sk is None:
            return None
        items = []
        for c in sk.sketchCurves:
            t = type(c).__name__
            if t == 'SketchCircle':
                items.append({'t':'circle','c':[round(c.centerSketchPoint.geometry.x*10,3), round(c.centerSketchPoint.geometry.y*10,3)],'d':round(c.radius*20,3)})
            elif t == 'SketchLine':
                s=c.startSketchPoint.geometry; e=c.endSketchPoint.geometry
                items.append({'t':'line','s':[round(s.x*10,2),round(s.y*10,2)],'e':[round(e.x*10,2),round(e.y*10,2)]})
            else:
                items.append({'t':t})
            if len(items)>=limit: break
        return {'isVisible': sk.isVisible, 'count': sk.sketchCurves.count, 'items': items}

    for s in ['Sketch13','Sketch15','Sketch17','Sketch4','Sketch14']:
        out[s] = dump(s)

    print(json.dumps(out))

