import adsk.core, adsk.fusion, json, math

def run(context):
    app = adsk.core.Application.get()
    root = app.activeProduct.rootComponent
    body = root.bRepBodies.item(0)
    nm = {0:'SOLID', 1:'ON', 2:'VOID', -1:'?'}

    def probe(x, y, z):
        p = adsk.core.Point3D.create(x/10.0, y/10.0, z/10.0)
        return nm.get(body.pointContainment(p), '?')

    a = 5.0 + 5.0*math.sqrt(3.0)
    b = 25.0 + 5.0*math.sqrt(3.0)
    out = {}

    # LOWER tab (-95, a): tab solid 0-5, pocket 2.5-5, floor 0-2.5, screw hole through floor
    cx, cy = -95.0, a
    out['LOWER_tab'] = {
        'floor_kept_z1.0':   probe(cx+2.5, cy, 1.0),
        'floor_kept_z2.0':   probe(cx+2.5, cy, 2.0),
        'pocket_void_z3.5':  probe(cx+2.5, cy, 3.5),
        'screwhole_z1.0':    probe(cx, cy, 1.0),
        'tab_wall_z3.5':     probe(cx+4.5, cy, 3.5),
    }

    # UPPER tab (-95, b): tab solid 5-10, pocket 7.5-10, floor 5-7.5
    cx2, cy2 = -95.0, b
    out['UPPER_tab'] = {
        'floor_kept_z6.0':   probe(cx2+2.5, cy2, 6.0),
        'pocket_void_z8.5':  probe(cx2+2.5, cy2, 8.5),
        'screwhole_z6.0':    probe(cx2, cy2, 6.0),
        'tab_wall_z8.5':     probe(cx2+4.5, cy2, 8.5),
        'below_tab_z2.0':    probe(cx2+2.5, cy2, 2.0),
    }

    # ORIENTATION TEST on a left-edge tab: vertex must point along X, flat along Y
    # R=3.464 (point dir), AF/2=3.0 (flat dir). At pocket level z=3.5:
    out['orientation_left_edge'] = {
        'along_X_3.2_expect_VOID(point dir)': probe(cx+3.2, cy, 3.5),
        'along_Y_3.2_expect_SOLID(flat dir)': probe(cx, cy+3.2, 3.5),
    }

    # ORIENTATION TEST on a top-edge tab: vertex along Y, flat along X
    cx3, cy3 = b, 95.0   # LOWER family top-edge tab (33.66, 95)
    out['orientation_top_edge'] = {
        'along_Y_3.2_expect_VOID(point dir)': probe(cx3, cy3+3.2, 3.5),
        'along_X_3.2_expect_SOLID(flat dir)': probe(cx3+3.2, cy3, 3.5),
    }

    print(json.dumps(out))

