import adsk.core, json

def run(context):
    app = adsk.core.Application.get()
    root = app.activeProduct.rootComponent
    body = [b for b in root.bRepBodies if b.name=='Body1'][0]

    STEP = 3.0
    RNG = 66.0
    n = int(RNG*2/STEP)+1
    xs = [-RNG + i*STEP for i in range(n)]

    solid = set()
    for i,x in enumerate(xs):
        for j,y in enumerate(xs):
            p = adsk.core.Point3D.create(x/10.0, y/10.0, 0.9)
            if body.pointContainment(p) == 0:
                solid.add((i,j))

    best = []
    maxk = 10
    for (i,j) in solid:
        k = 0
        while k < maxk:
            k += 1
            ok = True
            for di in range(-k, k+1):
                for dj in range(-k, k+1):
                    if di*di + dj*dj <= k*k:
                        if (i+di, j+dj) not in solid:
                            ok = False; break
                if not ok: break
            if not ok:
                k -= 1
                break
        if k >= 2:
            best.append((k*STEP, round(xs[i],1), round(xs[j],1)))

    best.sort(reverse=True)
    print(json.dumps({'solid_pts': len(solid), 'top_clearances_mm_x_y': best[:25]}))

