import adsk.core, json

def run(context):
    app = adsk.core.Application.get()
    root = app.activeProduct.rootComponent
    body = [b for b in root.bRepBodies if b.name=='Body1'][0]
    nm = {0:'SOLID',1:'ON',2:'VOID',-1:'?'}
    def probe(x,y,z):
        return nm.get(body.pointContainment(adsk.core.Point3D.create(x/10.0,y/10.0,z/10.0)),'?')

    out = {}
    # Is the T engraving present? stem of T near x=0, upper area of letter
    out['T_check'] = {
        'in_engrave_z9.6_(0,20)': probe(0,20,9.6),
        'below_engrave_z8.0_(0,20)': probe(0,20,8.0),
        'outside_letter_z9.6_(9,20)': probe(9,20,9.6),
        'in_engrave_z9.6_(0,17)': probe(0,17,9.6),
    }

    # all planar faces sitting flat at z~0
    flat0 = []
    for i,f in enumerate(body.faces):
        g = f.geometry
        if g.surfaceType != adsk.core.SurfaceTypes.PlaneSurfaceType: continue
        bb = f.boundingBox
        if abs(bb.minPoint.z) < 1e-5 and abs(bb.maxPoint.z) < 1e-5:
            n = adsk.core.Plane.cast(g).normal
            flat0.append({'idx':i,'area_mm2':round(f.area*100,1),'nz':round(n.z,3),'loops':f.loops.count})
    flat0.sort(key=lambda d:-d['area_mm2'])
    out['faces_at_z0'] = flat0[:5]
    out['count_at_z0'] = len(flat0)
    print(json.dumps(out))

