import adsk.core, json

def run(context):
    app = adsk.core.Application.get()
    target = None
    for doc in app.documents:
        if doc.name == 'Untitled':
            target = doc; break
    if target: target.activate()
    root = app.activeProduct.rootComponent
    out = {'active': app.activeDocument.name}
    out['bodies'] = [(b.name, round(b.physicalProperties.volume,4)) for b in root.bRepBodies]
    print(json.dumps(out))

