import adsk.core, adsk.fusion, json

def run(context):
    tdq = adsk.fusion.ThreadDataQuery.create(False)
    tname = tdq.defaultMetricThreadType
    sizes = list(tdq.allSizes(tname))
    out = {'all_sizes_near_3': [s for s in sizes if s.strip() in ('2.5','2.8','3.0','3','3.5','4.0','4','5.0','5','6.0','6')]}
    for cand in ['3.0','3']:
        desigs = tdq.allDesignations(tname, cand)
        out[f'designations_for_{cand}'] = list(desigs)
        if desigs:
            out[f'classes_for_{cand}_first'] = list(tdq.allClasses(tname, desigs[0]))
    print(json.dumps(out))

