import adsk.core, adsk.fusion, json

def run(context):
    app = adsk.core.Application.get()
    root = app.activeProduct.rootComponent
    nut = [b for b in root.bRepBodies if b.name=='HexNut_M6_Body'][0]
    out = {}
    out['extrudes'] = [f.name for f in root.features.extrudeFeatures]
    out['sketches'] = [s.name for s in root.sketches]
    out['nut_bbox_mm'] = [round(nut.boundingBox.minPoint.z*10,3), round(nut.boundingBox.maxPoint.z*10,3)]

    for f in root.features.extrudeFeatures:
        if f.name == 'NutBlindHole':
            ext = f.extentOne
            out['blind_extent_type'] = type(ext).__name__
            try:
                out['blind_distance_cm'] = ext.distance.value
            except Exception as e:
                out['blind_distance_err'] = str(e)

    # scan cylindrical faces in the nut, report their Z spans
    cyl_faces = []
    for fc in nut.faces:
        g = fc.geometry
        if g.surfaceType == adsk.core.SurfaceTypes.CylinderSurfaceType:
            bb = fc.boundingBox
            cyl_faces.append([round(bb.minPoint.z*10,3), round(bb.maxPoint.z*10,3), round(g.radius*10,3)])
    out['cyl_faces_z_r'] = cyl_faces
    print(json.dumps(out))

