import adsk.core, json, math
from collections import defaultdict, Counter

def run(context):
    app = adsk.core.Application.get()
    root = app.activeProduct.rootComponent
    body = [b for b in root.bRepBodies if b.name=='Body1'][0]

    def mm(v): return round(v*10.0, 2)

    # 4.5mm holes on the deck
    centers = set()
    for face in body.faces:
        g = face.geometry
        if g.surfaceType != adsk.core.SurfaceTypes.CylinderSurfaceType:
            continue
        cyl = adsk.core.Cylinder.cast(g)
        ax = cyl.axis
        if abs(abs(ax.z)-1.0) > 0.01: continue
        if round(cyl.radius*20,2) != 4.5: continue
        centers.add((mm(cyl.origin.x), mm(cyl.origin.y)))

    deck = sorted([(x,y) for (x,y) in centers if math.hypot(x,y) <= 78])

    # axis-aligned pairs only (usable for rectangular brackets)
    x_pairs = Counter()  # same Y, spacing along X
    y_pairs = Counter()  # same X, spacing along Y
    for i,(x1,y1) in enumerate(deck):
        for x2,y2 in deck[i+1:]:
            if abs(y1-y2) < 0.05 and 0.1 < abs(x2-x1) < 60:
                x_pairs[round(abs(x2-x1),1)] += 1
            if abs(x1-x2) < 0.05 and 0.1 < abs(y2-y1) < 60:
                y_pairs[round(abs(y2-y1),1)] += 1

    print(json.dumps({
        'top_X_spacings': x_pairs.most_common(15),
        'top_Y_spacings': y_pairs.most_common(15),
    }))

