import adsk.core, adsk.fusion, math, json, traceback

def run(context):
    try:
        app = adsk.core.Application.get()
        assert app.activeDocument.name == 'Untitled'
        root = app.activeProduct.rootComponent
        log = {}

        # Delete features by walking timeline in REVERSE
        tl = app.activeProduct.timeline
        while tl.count > 0:
            try:
                tl.item(tl.count - 1).entity.deleteMe()
            except:
                break

        # Delete any orphaned bodies
        for b in list(root.bRepBodies):
            try: b.deleteMe()
            except: pass

        log['after_cleanup'] = {'bodies': root.bRepBodies.count, 'features': root.features.extrudeFeatures.count,
                                'sketches': root.sketches.count, 'planes': root.constructionPlanes.count}
        print(json.dumps(log))
    except:
        print('ERROR: ' + traceback.format_exc())

