import adsk.core, adsk.fusion, json, traceback

def run(context):
    try:
        app = adsk.core.Application.get()
        assert app.activeDocument.name == 'Bloc'
        root = app.activeProduct.rootComponent
        B = {b.name: b for b in root.bRepBodies}
        before = {k: round(v.physicalProperties.volume,4) for k,v in B.items()}
        dup = ['MountThread (2)', 'MountThread (1)', 'SlideThread (1)']
        removed = []
        for n in dup:
            for t in list(root.features.threadFeatures):
                if t.name == n:
                    t.deleteMe(); removed.append(n)
        B = {b.name: b for b in root.bRepBodies}
        after = {k: round(v.physicalProperties.volume,4) for k,v in B.items()}
        names = [t.name for t in root.features.threadFeatures]
        health = {t.name: str(t.healthState) for t in root.features.threadFeatures}
        print(json.dumps({'removed': removed, 'remaining': names, 'health': health, 'vol_before': before, 'vol_after': after}))
    except:
        print('ERROR: ' + traceback.format_exc())

