import adsk.core, json

def run(context):
    app = adsk.core.Application.get()
    out = []
    for d in app.documents:
        try:
            des = d.products.itemByProductType('DesignProductType')
            out.append({'name': d.name, 'saved': d.isSaved, 'timeline': des.timeline.count if des else None,
                        'bodies': des.rootComponent.bRepBodies.count if des else None})
        except Exception as e:
            out.append({'name': d.name, 'err': str(e)})
    print(json.dumps({'active': app.activeDocument.name, 'docs': out}))

